		t.Errorf("Bitcoin(0) formatted as text = %q, want %q", got, want)
	}
}

func TestAmountBuildsABitcoin(t *testing.T) {
	got := Amount(25)
	if got != Bitcoin(25) {
		t.Fatalf("Amount(25) = %d, want a Bitcoin worth 25", int(got))
	}

	described := fmt.Sprintf("%s", got)
	want := "25 BTC"
	if described != want {
		t.Errorf("Amount(25) formatted as text = %q, want %q", described, want)
	}
}

