package exercise

import "testing"

func TestWithdrawWhenTheWalletCanCoverIt(t *testing.T) {
	wallet := Wallet{}
	wallet.Deposit(20)

	err := wallet.Withdraw(10)
	if err != nil {
		t.Fatalf("Withdraw(10) from a wallet holding 20 reported %q, want no failure", err.Error())
	}
	if got := wallet.Balance(); got != 10 {
		t.Errorf("Balance() after withdrawing 10 from 20 = %d, want 10", got)
	}
}

func TestWithdrawTheWholeBalance(t *testing.T) {
	wallet := Wallet{}
	wallet.Deposit(20)

	err := wallet.Withdraw(20)
	if err != nil {
		t.Fatalf("Withdraw(20) from a wallet holding 20 reported %q, want no failure", err.Error())
	}
	if got := wallet.Balance(); got != 0 {
		t.Errorf("Balance() after withdrawing the whole balance = %d, want 0", got)
	}
}

func TestWithdrawMoreThanTheWalletHolds(t *testing.T) {
	wallet := Wallet{}
	wallet.Deposit(20)

	err := wallet.Withdraw(100)
	if err == nil {
		t.Fatal("Withdraw(100) from a wallet holding 20 reported no failure, want a failure")
	}
	if got, want := err.Error(), "cannot withdraw, insufficient funds"; got != want {
		t.Errorf("failure message = %q, want %q", got, want)
	}
	if got := wallet.Balance(); got != 20 {
		t.Errorf("Balance() after a rejected withdrawal = %d, want 20 (unchanged)", got)
	}
}

